return new { playing=UnityEditor.EditorApplication.isPlaying, scenes=Enumerable.Range(0,UnityEngine.SceneManagement.SceneManager.sceneCount).Select(i=>new {path=UnityEngine.SceneManagement.SceneManager.GetSceneAt(i).path,dirty=UnityEngine.SceneManagement.SceneManager.GetSceneAt(i).isDirty}).ToArray(), animators=UnityEngine.Object.FindObjectsByType<Animator>(FindObjectsInactive.Include,FindObjectsSortMode.None).Select(a=>new {name=a.name,path=UnityEditor.AnimationUtility.CalculateTransformPath(a.transform,null),avatar=UnityEditor.AssetDatabase.GetAssetPath(a.avatar),controller=UnityEditor.AssetDatabase.GetAssetPath(a.runtimeAnimatorController)}).ToArray(), background=Application.runInBackground };

